  function initials(name){return (name||'MY').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
  function setAuthMessage(msg,error=false){$('#authMessage').textContent=msg;$('#authMessage').style.color=error?'#b33a2e':''}
  function frAuthError(err){const m=String(err?.message||err||'');if(/invalid login|invalid credentials/i.test(m))return 'E-mail ou mot de passe incorrect.';if(/email not confirmed/i.test(m))return 'Adresse e-mail non confirmée. Vérifiez votre boîte de réception.';if(/failed to fetch|network|load failed/i.test(m))return 'Connexion impossible : vérifiez votre accès Internet.';if(/rate limit|too many/i.test(m))return 'Trop de tentatives. Patientez quelques minutes avant de réessayer.';return m||'Connexion impossible.'}
  async function login(e){e.preventDefault();if(!sb)return setAuthMessage('Configuration Supabase manquante.',true);const email=$('#email').value.trim(),password=$('#password').value;if(!email||!password){setAuthMessage('Saisissez votre e-mail et votre mot de passe.',true);(email?$('#password'):$('#email')).focus();return}const btn=$('#loginBtn'),label=btn?.querySelector('span');const reset=()=>{if(btn){btn.disabled=false;btn.classList.remove('loading')}if(label)label.textContent='Se connecter'};if(btn){btn.disabled=true;btn.classList.add('loading')}if(label)label.textContent='Connexion…';setAuthMessage('Vérification de vos identifiants…');try{const {error}=await sb.auth.signInWithPassword({email,password});if(error)return setAuthMessage(frAuthError(error),true);setAuthMessage('Connexion réussie.');await boot()}catch(err){setAuthMessage(frAuthError(err),true)}finally{reset()}}
  async function logout(){forgetSession();showAuth('Vous êtes déconnecté.');if(!sb)return;let failed=false;try{const {error}=await sb.auth.signOut({scope:'local'});failed=!!error}catch(_){failed=true}if(failed){/* hors ligne : Supabase garde la session si le serveur ne répond pas, on l'efface nous-mêmes */try{const k=sb.auth.storageKey;if(k){localStorage.removeItem(k);localStorage.removeItem(k+'-code-verifier');localStorage.removeItem(k+'-user')}}catch(_){}}}
  function applyIdentity(user,profile){const name=profile.full_name||user.email||'Utilisateur';$('#userName').textContent=name;$('#userRole').textContent=({owner:'Super Administrateur',admin:'Administrateur',manager:'Gestionnaire',employee:'Employé'}[profile.role]||profile.role);setAvatarElements(profile,name)}
  function rememberSession(user,profile){localStorage.setItem(lastAuthKey,JSON.stringify({id:user.id,email:user.email||null,lastValidatedAt:new Date().toISOString()}));writeOffline('profile:'+user.id,profile)}
  async function enterWorkspace(user,profile,offlineMode=false,opts={}){state.user=user;state.profile=profile;if(!offlineMode)rememberSession(user,profile);hideSplash();$('#authView').classList.add('hidden');$('#appView').classList.remove('hidden');applyIdentity(user,profile);$('#topAvatar').onclick=()=>navigate('profile');$('#userAvatar').onclick=()=>navigate('profile');$('#year').textContent=new Date().getFullYear();renderNav();await navigate(startPage(),{replace:true});updateOutboxBadge();if(opts.deferSync)return;if(navigator.onLine)syncOutbox();else toast('Session locale restaurée. Certaines opérations nécessitent Internet.')}
  /* Démarrage : si cet appareil a déjà ouvert une session (utilisateur mémorisé + profil actif en cache),
     l'espace s'ouvre tout de suite, en ligne comme hors ligne. La session Supabase est ensuite vérifiée
     en arrière-plan ; seul un refus définitif du serveur (session révoquée, profil désactivé) renvoie à
     l'écran de connexion. Un réseau absent, lent ou instable ne déconnecte jamais. */
  function hideSplash(){$('#bootSplash')?.remove()}
  function showAuth(msg='',isError=false){hideSplash();state.user=null;state.profile=null;$('#appView').classList.add('hidden');$('#authView').classList.remove('hidden');if(msg)setAuthMessage(msg,isError)}
  function forgetSession(){const id=state.user?.id;localStorage.removeItem(lastAuthKey);if(id){try{const all=JSON.parse(localStorage.getItem(offlineKey)||'{}');delete all['profile:'+id];localStorage.setItem(offlineKey,JSON.stringify(all))}catch(_){}}}
  function rememberedLocal(){let r=null;try{r=JSON.parse(localStorage.getItem(lastAuthKey)||'null')}catch(_){}if(!r?.id)return null;const profile=readOffline('profile:'+r.id);return profile?.is_active?{user:{id:r.id,email:r.email||null},profile}:null}
  const withTimeout=(promise,ms)=>Promise.race([promise,new Promise((_,reject)=>setTimeout(()=>reject(Object.assign(new Error('Délai réseau dépassé'),{name:'TimeoutError'})),ms))]);
  const isNetworkError=err=>!navigator.onLine||err?.name==='TimeoutError'||err?.name==='AuthRetryableFetchError'||err?.status===0||/fetch|network|timeout|load failed|connexion/i.test(String(err?.message||''));
  async function boot(){
    if(!sb){showAuth('Impossible de charger Supabase. Vérifiez js/config.js.',true);return}
    const local=rememberedLocal();let opened=false;
    if(local){opened=true;await enterWorkspace(local.user,local.profile,true,{deferSync:true})}
    const sameUser=id=>opened&&state.user?.id===id;
    const keepLocal=()=>{if(!navigator.onLine)toast('Session locale restaurée. Certaines opérations nécessitent Internet.')};
    let session=null,sessionError=null;
    try{const r=await withTimeout(sb.auth.getSession(),10000);session=r?.data?.session||null;sessionError=r?.error||null}catch(err){sessionError=err}
    if(!session){
      if(opened){
        const definitive=sessionError?!isNetworkError(sessionError):navigator.onLine;
        if(!definitive)return keepLocal();
        forgetSession();return showAuth('Votre session a expiré. Reconnectez-vous.',true)
      }
      return showAuth(navigator.onLine?'':'Première connexion requise avec Internet pour activer l’accès hors connexion.',!navigator.onLine)
    }
    let profile=null,profileError=null;
    try{const r=await withTimeout(sb.from('profiles').select('*').eq('id',session.user.id).maybeSingle(),10000);profile=r.data;profileError=r.error}catch(err){profileError=err}
    if(profile?.is_active){
      if(sameUser(session.user.id)){state.user=session.user;state.profile=profile;rememberSession(session.user,profile);applyIdentity(session.user,profile);updateOutboxBadge();if(navigator.onLine)syncOutbox();return}
      return enterWorkspace(session.user,profile,false)
    }
    if(profileError){
      if(sameUser(session.user.id))return keepLocal();
      const cached=readOffline('profile:'+session.user.id);
      if(cached?.is_active)return enterWorkspace(session.user,cached,true);
      return showAuth('Impossible de vérifier votre profil pour le moment. Réessayez dans un instant.',true)
    }
    await sb.auth.signOut().catch(()=>{});forgetSession();showAuth('Profil introuvable ou désactivé. Contactez le propriétaire.',true)
  }
