  function renderNav(){const nav=$('#navigation');const collapsed=navCollapsed();nav.innerHTML=groups.map(g=>{const hasActive=g.items.some(([id])=>id===state.page);const open=hasActive||!collapsed.includes(g.label);return `<div class="nav-section ${open?'':'collapsed'}" data-group="${esc(g.label)}"><button type="button" class="nav-group" aria-expanded="${open}">${esc(g.label)}<i class="fa-solid fa-chevron-down" aria-hidden="true"></i></button><div class="nav-items">`+g.items.map(([id,label,ico])=>`<button type="button" class="nav-item ${state.page===id?'active':''}" data-page="${id}" ${state.page===id?'aria-current="page"':''}><i class="fa-solid ${ico}" aria-hidden="true"></i><span>${esc(label)}</span></button>`).join('')+`</div></div>`}).join('');nav.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>{navigate(b.dataset.page);$('#sidebar').classList.remove('open');document.body.classList.remove('nav-open')}));nav.querySelectorAll('.nav-group').forEach(b=>b.addEventListener('click',()=>{const sec=b.closest('.nav-section');const label=sec.dataset.group;const nowCollapsed=!sec.classList.contains('collapsed');sec.classList.toggle('collapsed',nowCollapsed);b.setAttribute('aria-expanded',String(!nowCollapsed));let list=navCollapsed().filter(x=>x!==label);if(nowCollapsed)list.push(label);try{localStorage.setItem(navCollapsedKey,JSON.stringify(list))}catch(_){}}))}
