    const totalSales=seg.reduce((a,s)=>a+s.rows.length,0);const R=50,C=2*Math.PI*R;let off=0;
    const arcs=totalSales?seg.filter(s=>s.rows.length).map(s=>{const len=C*s.rows.length/totalSales;const vis=Math.max(0,len-(seg.filter(z=>z.rows.length).length>1?4:0));const o=off;off+=len;return `<circle cx="64" cy="64" r="${R}" fill="none" stroke="${s.color}" stroke-width="16" stroke-linecap="round" stroke-dasharray="${vis.toFixed(1)} ${(C-vis).toFixed(1)}" stroke-dashoffset="${(-o-2).toFixed(1)}" transform="rotate(-90 64 64)"><title>${s.label} : ${s.rows.length}</title></circle>`}).join(''):'';
