  function cellValue(k,v){if(k==='image_url')return v?`<span class="thumb"><img src="${esc(v)}" alt="" loading="lazy"></span>`:'<span class="thumb ph"><i class="fa-solid fa-jar" aria-hidden="true"></i></span>';if(k==='full_name'&&v)return avatarCell(v);if(k.includes('date'))return date(v);if(['total','amount','subtotal','discount','amount_paid','sale_price','cost_price','average_cost','current_balance','opening_balance'].includes(k))return money(v);if(k.endsWith('_id')&&v){const n=(state.names||{})[v];if(n)return avatarCell(n)}if(k==='is_active')return v?'<span class="pill">Actif</span>':'<span class="pill off">Inactif</span>';if(k==='status')return status(v);return esc(v??'—')}
